import{n as e,t}from"./index-JTf8835h.js";function n(){return t(e,{children:[t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-1.jpg`,loading:`lazy`}),t(`p`,{children:`The mandelbrot fractal is an extremely interesting little mathmatical wonder. It's a simple formula, defined as:`}),t(`p`,{children:[`f`,t(`sub`,{children:`c`}),`(z)=z`,t(`sup`,{children:`2`}),`+c`]}),t(`p`,{children:`Where z starts at 0.`}),t(`p`,{children:`Okay, but what does this actually mean in simple words us humans can understand? A number is in the mandelbrot set if f(0) does not escape to infinity, and if f(f(0)) dosent, and if f(f(f(0))) dosent, you get the point. The function can iterate infinite times and the number never escapes to infinity.`}),t(`p`,{children:`How does it not go to infinity though if you iterate infinite times? Well, think of a number like 2. 2 squared is 4. If I keep squaring it the number expands to infinity. Now what about 1? 1 squared is still 1. Okay now what about a number like 0.5 (1/2)? 0.5 squared is 0.25 (1/4). I can square this as many times as I want and it never reaces infinity.`}),t(`p`,{children:`As long as a number remains in the range of [-1,1], it will never reach infinity when squared indefinitely.`}),t(`p`,{children:`However with the '+ c' in the formula this changes things. Now the number escaping depends not only on z but c as well.`}),t(`p`,{children:[`Okay, so c is a complex number (re + im). That's ANY number. And, z is part of the function's `,t(`i`,{children:`iteration`}),`. The function can be represented pretty simply in code. Here's some pseudocode to demonstrate:`]}),t(`pre`,{class:`bg-zinc-900 text-zinc-100 p-4 rounded-lg overflow-x-auto text-sm font-mono`,children:t(`code`,{children:`def is_in_mandelbrot_set(c):
    z = 0
    for 0..infinity:
        z = pow(z, 2) + c

        if (z == infinity):
            return False
        else:
            return True`})}),t(`p`,{children:`If you've noticed, the 'function' mentions a 'set'. This is what we know as the mandelbrot fractal. The mandelbrot set is a set of all complex numbers that don't escape to infinity when passed through this function infinite times.`}),t(`p`,{children:`Okay... so the mandelbrot set is just a bunch of numbers that don't escape to infinity. But how do we get these incredible visualizations? Well, these renderings are based off of the real and complex portions of all the numbers in the set.`}),t(`p`,{children:`Genearlly, image renderings show the real part of the complex number on the x axis, and the imaginary part on the y axis. The complex numbers represented by re + im are now mapped to (x,y) cordinates via (re, im).`}),t(`p`,{children:`Then, we calculate if the number is part of the set and color it if it is.`}),t(`p`,{children:`But then if we just plot the image we get a really generic black and white photo... what gives?`}),t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-2.jpg`,loading:`lazy`}),t(`p`,{children:`Well yeah, but this is all still theoretical. After all our function cannot possibly actually iterate to infinity.`}),t(`p`,{children:`In reality we escape the function after z escapes some arbitrary 'bailout' number we (the programmer/user) get to decide. Then we can use the number of iterations it took to sample colors from a colormap.`}),t(`p`,{children:`This spices up rendering quite a bit, and also makes it actually possible to render since we're not going all the way to inifnity!`}),t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-3.jpg`,loading:`lazy`}),t(`p`,{children:`Great... now we have colorful renderings of the mandelbrot fractal! It's worth noting that any value outside the range of Re [-2.5, 1] and Im [-1, 1] all escape to infinity, so for all the visualizations I've shown, the numbers all lie within this range.`}),t(`p`,{children:`Now it gets really intersting. We can 'zoom in' on the fractal on any given point where there's 'activity' and start to see some truly incredible patterns emmerge.`}),t(`p`,{children:`Calculating 'activity' and 'zoom' is outside the scope of this blog post, but still worth looking into.`}),t(`p`,{children:[`All of my visualizations are made with my own rendering program,`,` `,t(`a`,{href:`https://github.com/Logan-010/mbrot`,target:`_blank`,children:`mbrot`}),`. Go check it out! The code is all open source so feel free to inspect the actual real rendering algorithom`]}),t(`p`,{children:`Anyway, as a send off, here's some cool fractals.`}),t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-4.jpg`,loading:`lazy`}),t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-5.jpg`,loading:`lazy`}),t(`img`,{src:`/blog/the-mandelbrot-fractal/brot-6.jpg`,loading:`lazy`})]})}export{n as default};